window.docContents[139].resolve({"/rules/PL1005/#PL1005-rationale":{"contents":"A profile claim tells readers which logical principles every result on the surface may use. One declaration above the bound makes the claim false for the whole surface.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1005: Transitive axioms must fit the selected profile","header":"Why it matters","id":"/rules/PL1005/#PL1005-rationale"},"/rules/PL2004/#PL2004-rationale":{"contents":"A conformance claim covers an exact set of modules. A module imported into a claimed library but outside every surface would contribute declarations nobody classified, and an umbrella import alone does not define that set.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL2004: Owned coverage must match the exact Lake inventory","header":"Why it matters","id":"/rules/PL2004/#PL2004-rationale"},"/rules/PL4002/#PL4002-rationale":{"contents":"Readers copy documented examples and trust them. A positive example that does not elaborate, or that proves its claim with an axiom, teaches a false claim.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL4002: Positive examples require warning-free elaboration and admission","header":"Why it matters","id":"/rules/PL4002/#PL4002-rationale"},"/rules/PL5001/#PL5001-rationale":{"contents":"Module documentation tells a reader which declarations carry the module's claims and under which assumptions, so the claims can be reviewed without reading every proof.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL5001: Claimed modules require module documentation","header":"Why it matters","id":"/rules/PL5001/#PL5001-rationale"}});